-- Central administration over existing workspaces. Existing business rows and
-- grants are retained; no schema/data merge and no service credentials in UI.
create table private.org_departments(id bigint generated by default as identity primary key,title text not null check(length(trim(title)) between 1 and 160),active boolean not null default true,revision bigint not null default 1);
create table private.org_units(id bigint generated by default as identity primary key,department_id bigint not null references private.org_departments(id),parent_id bigint references private.org_units(id),title text not null check(length(trim(title)) between 1 and 160),schema_name text not null check(schema_name in ('public','bamco_process','bamco_quality')),local_unit_id bigint not null,active boolean not null default true,features_configured boolean not null default false,revision bigint not null default 1,unique(schema_name,local_unit_id));
create table private.org_members(schema_name text not null check(schema_name in ('public','bamco_process','bamco_quality')),user_id uuid not null,unit_id bigint not null references private.org_units(id),primary key(schema_name,user_id));
create table private.org_packages(id bigint generated by default as identity primary key,title text not null check(length(trim(title)) between 1 and 160),active boolean not null default true,revision bigint not null default 1);
create table private.org_package_grants(package_id bigint not null references private.org_packages(id) on delete cascade,feature_key text not null,actions text[] not null check(actions <@ array['view','create','edit','delete','export']),primary key(package_id,feature_key));
create table private.org_bindings(id bigint generated by default as identity primary key,package_id bigint not null references private.org_packages(id),unit_id bigint not null references private.org_units(id),user_id uuid,active boolean not null default true);
create unique index org_binding_identity on private.org_bindings(package_id,unit_id,coalesce(user_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table private.org_unit_features(unit_id bigint not null references private.org_units(id),feature_key text not null,primary key(unit_id,feature_key));
create index org_members_by_unit on private.org_members(unit_id);
create index org_bindings_active_unit on private.org_bindings(unit_id,user_id,package_id) where active;
create table private.org_admin_audit(id bigint generated always as identity primary key,actor_id uuid not null,action text not null,payload jsonb not null,created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['org_departments','org_units','org_members','org_packages','org_package_grants','org_bindings','org_unit_features','org_admin_audit'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated',t);end loop;end$$;

-- Safe defaults: existing accounts retain their old grants. New packages are
-- reusable templates, but they grant nothing until explicitly assigned.
do $$declare ns text;dept bigint;local_id bigint;global_id bigint;pid bigint;entry record;label text;begin
 insert into private.org_departments(title) values(coalesce((select title from public.organization_positions where active and parent_position_id is null order by id limit 1),'معاونت فنی، مهندسی و کیفیت')) returning id into dept;
 foreach ns in array array['public','bamco_process','bamco_quality'] loop
  label:=case ns when 'public' then 'مهندسی توسعه و تکوین محصول' when 'bamco_process' then 'مدیریت فرآیند' else 'کنترل کیفیت' end;
  execute format('select id from %I.organization_units where active order by id limit 1',ns) into local_id;
  if local_id is null then execute format('insert into %I.organization_units(title,code) values($1,$2) returning id',ns) into local_id using label,'ADMIN-ROOT';end if;
  insert into private.org_units(department_id,title,schema_name,local_unit_id) values(dept,label,ns,local_id) returning id into global_id;
  execute format('insert into private.org_members(schema_name,user_id,unit_id) select $1,id,$2 from %I.profiles where role<>''manager''',ns) using ns,global_id;
  execute format('update %I.organization_positions set unit_id=$1 where unit_id is null',ns) using local_id;
 end loop;
 for entry in select * from (values('مشاهده‌کننده',array['view']),('ثبت‌کننده',array['view','create']),('ویرایشگر',array['view','create','edit']),('تأییدکننده',array['view']),('مدیر واحد',array['view','create','edit','delete','export'])) x(title,actions) loop
  insert into private.org_packages(title) values(entry.title) returning id into pid;
  insert into private.org_package_grants(package_id,feature_key,actions) select pid,feature_key,case when feature_key in ('people','organization','systemOptions','templates','activeSessions','loginActivity') then array['view'] when entry.title='تأییدکننده' and feature_key='approvals' then array['view','edit'] else entry.actions end from public.app_features where active and feature_key<>'organizationAdmin';
 end loop;
end$$;

create function private.org_require_admin() returns void language plpgsql stable security definer set search_path='' as $$begin
 if auth.uid() is null or not private.is_system_manager(auth.uid()) then raise exception 'این پنل فقط برای ادمین کل سامانه است.' using errcode='42501';end if;
end$$;
revoke all on function private.org_require_admin() from public,anon,authenticated;

-- -1 is an explicit unit ceiling/direct deny, 0 preserves the previous policy,
-- +1 adds a package capability. Object-specific RLS remains authoritative.
create function private.org_permission_decision(p_schema text,p_actor uuid,p_feature text,p_action text,p_resource_type text,p_resource_id text) returns integer language plpgsql stable security definer set search_path='' as $$
declare member private.org_members;u private.org_units;valid boolean;denied boolean;begin
 if p_schema not in ('public','bamco_process','bamco_quality') then return -1;end if;
 if p_feature='organizationAdmin' then return -1;end if;
 select * into member from private.org_members where schema_name=p_schema and user_id=p_actor;
 if found then
  select * into u from private.org_units where id=member.unit_id;
  if not u.active or not exists(select 1 from private.org_departments where id=u.department_id and active) then return -1;end if;
  if u.features_configured and not exists(select 1 from private.org_unit_features where unit_id=u.id and feature_key=p_feature) then return -1;end if;
 else return 0;end if;
 if p_action not in ('view','create','edit','delete','export') then return 0;end if;
 if p_action<>'view' and p_feature in ('people','organization','systemOptions','templates','activeSessions','loginActivity') then return 0;end if;
 execute format('select exists(select 1 from %I.profiles where id=$1 and active) and exists(select 1 from %I.app_features where feature_key=$2 and active)',p_schema,p_schema) into valid using p_actor,p_feature;
 if not valid then return -1;end if;
 execute format('select exists(select 1 from %I.feature_access_grants where subject_kind=''user'' and user_id=$1 and feature_key=$2 and effect=''deny'' and revoked_at is null and (resource_type is null or (resource_type is not distinct from $3 and resource_id is not distinct from $4)))',p_schema) into denied using p_actor,p_feature,p_resource_type,p_resource_id;
 if denied then return -1;end if;
 if exists(select 1 from private.org_bindings b join private.org_packages p on p.id=b.package_id and p.active join private.org_package_grants g on g.package_id=p.id where b.active and b.unit_id=u.id and (b.user_id is null or b.user_id=p_actor) and g.feature_key=p_feature and p_action=any(g.actions)) then return 1;end if;
 return 0;
end$$;
revoke all on function private.org_permission_decision(text,uuid,text,text,text,text) from public,anon,authenticated;

-- Preserve the current canonical function as the fallback, including explicit
-- deny, role grants, resource filters and all existing workflow semantics.
do $$declare ns text;hidden text;definition text;begin
 foreach ns in array array['public','bamco_process','bamco_quality'] loop
  hidden:=case ns when 'public' then 'private' else ns||'_private' end;
  definition:=pg_get_functiondef(to_regprocedure(hidden||'.feature_can_access_for(uuid,text,text,text,text)'));
  if definition is null then raise exception 'Authorization baseline missing: %',ns;end if;
  execute replace(definition,hidden||'.feature_can_access_for(',hidden||'.feature_can_access_before_org(');
  execute format('revoke all on function %I.feature_can_access_before_org(uuid,text,text,text,text) from public,anon,authenticated',hidden);
  execute format($body$
   create or replace function %1$I.feature_can_access_for(p_actor uuid,p_feature_key text,p_action text default 'view',p_resource_type text default null,p_resource_id text default null) returns boolean language plpgsql stable security definer set search_path='' as $fn$
   declare decision integer;begin
    if %1$I.is_system_manager(p_actor) then return %1$I.feature_can_access_before_org(p_actor,p_feature_key,p_action,p_resource_type,p_resource_id);end if;
    decision:=private.org_permission_decision(%2$L,p_actor,p_feature_key,p_action,p_resource_type,p_resource_id);
    if decision=-1 then return false;elsif decision=1 then return true;end if;
    return %1$I.feature_can_access_before_org(p_actor,p_feature_key,p_action,p_resource_type,p_resource_id);
   end $fn$;
  $body$,hidden,ns);
  execute format('insert into %I.app_features(feature_key,route_key,title,category,sort_order) values(''organizationAdmin'',''organizationAdmin'',''مدیریت جامع سازمان'',''people'',5) on conflict(feature_key) do nothing',ns);
 end loop;
end$$;

create function public.admin_org_prepare_workspace(p_schema text) returns boolean language plpgsql security definer set search_path='' as $$begin
 perform private.org_require_admin();
 if p_schema not in ('public','bamco_process','bamco_quality') then raise exception 'واحد معتبر نیست.';end if;
 if p_schema<>'public' then execute format('insert into %I.profiles select * from public.profiles where id=$1 on conflict(id) do nothing',p_schema) using auth.uid();end if;
 return true;
end$$;

create function public.admin_org_snapshot() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare ns text;result jsonb;data jsonb;scopes jsonb:='[]';begin
 perform private.org_require_admin();
 foreach ns in array array['public','bamco_process','bamco_quality'] loop
  execute format($query$select jsonb_build_object('schema_name',%1$L,
   'people',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',coalesce(display_name,full_name),'full_name',full_name,'login_name',login_name,'email',email,'active',active,'role',role) order by full_name),'[]') from %2$I.profiles),
   'roles',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'level_no',level_no) order by level_no desc),'[]') from %2$I.organization_roles where active),
   'positions',(select coalesce(jsonb_agg(to_jsonb(p) order by id),'[]') from %2$I.organization_positions p where active),
   'assignments',(select coalesce(jsonb_agg(to_jsonb(a)),'[]') from %2$I.organization_position_assignments a where is_primary and valid_from<=current_date and (valid_to is null or valid_to>current_date)),
   'features',(select coalesce(jsonb_agg(jsonb_build_object('feature_key',feature_key,'title',title,'category',category) order by sort_order),'[]') from %2$I.app_features where active and feature_key<>'organizationAdmin'))$query$,ns,ns) into data;
  scopes:=scopes||jsonb_build_array(data);
 end loop;
 select jsonb_build_object('departments',(select coalesce(jsonb_agg(to_jsonb(d) order by id),'[]') from private.org_departments d),'units',(select coalesce(jsonb_agg(to_jsonb(u) order by id),'[]') from private.org_units u),'members',(select coalesce(jsonb_agg(to_jsonb(m)),'[]') from private.org_members m),'packages',(select coalesce(jsonb_agg(to_jsonb(p) order by id),'[]') from private.org_packages p),'package_grants',(select coalesce(jsonb_agg(to_jsonb(g)),'[]') from private.org_package_grants g),'bindings',(select coalesce(jsonb_agg(to_jsonb(b)),'[]') from private.org_bindings b),'unit_features',(select coalesce(jsonb_agg(to_jsonb(f)),'[]') from private.org_unit_features f),'workspaces',scopes) into result;
 return result;
end$$;

create function public.admin_org_save(p_action text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare id_value bigint;revision_value bigint;u private.org_units;pkg private.org_packages;title_value text;ns text;local_id bigint;person uuid;feature text;actions_value text[];entry jsonb;saved jsonb;affected integer;begin
 perform private.org_require_admin();
 perform pg_advisory_xact_lock(hashtextextended('bamco.central.organization.admin',0));
 id_value:=nullif(p_payload->>'id','')::bigint;revision_value:=nullif(p_payload->>'revision','')::bigint;title_value:=nullif(trim(p_payload->>'title'),'');
 if p_action='department' then
  if title_value is null or length(title_value)>160 then raise exception 'عنوان معاونت معتبر نیست.';end if;
  if id_value is null then insert into private.org_departments(title) values(title_value) returning id into id_value;
  else update private.org_departments set title=title_value,active=coalesce((p_payload->>'active')::boolean,true),revision=revision+1 where id=id_value and revision=revision_value;get diagnostics affected=row_count;if affected<>1 then raise exception 'اطلاعات هم‌زمان تغییر کرده؛ تازه‌سازی کنید.';end if;end if;
 elsif p_action='unit' then
  if title_value is null or length(title_value)>160 then raise exception 'عنوان واحد معتبر نیست.';end if;
  if not exists(select 1 from private.org_departments where id=(p_payload->>'department_id')::bigint and active) then raise exception 'معاونت معتبر نیست.';end if;
  if id_value is null then
   ns:='public';
   if nullif(p_payload->>'parent_id','') is not null then select * into strict u from private.org_units where id=(p_payload->>'parent_id')::bigint and department_id=(p_payload->>'department_id')::bigint and active;ns:=u.schema_name;end if;
   execute format('insert into %I.organization_units(title,code,parent_unit_id,created_by) values($1,$2,$3,$4) returning id',ns) into local_id using title_value,'CENTRAL-'||gen_random_uuid()::text,u.local_unit_id,auth.uid();
   insert into private.org_units(title,department_id,parent_id,schema_name,local_unit_id,features_configured) values(title_value,(p_payload->>'department_id')::bigint,nullif(p_payload->>'parent_id','')::bigint,ns,local_id,true) returning id into id_value;
  else
   select * into strict u from private.org_units where id=id_value;
   if u.revision is distinct from revision_value then raise exception 'اطلاعات هم‌زمان تغییر کرده؛ تازه‌سازی کنید.';end if;
   -- Existing units retain their parent to avoid moving a populated subtree accidentally.
   update private.org_units set title=title_value,active=coalesce((p_payload->>'active')::boolean,true),revision=revision+1 where id=id_value;
   execute format('update %I.organization_units set title=$1,active=$2,updated_at=now() where id=$3',u.schema_name) using title_value,coalesce((p_payload->>'active')::boolean,true),u.local_unit_id;
  end if;
 elsif p_action='features' then
  select * into strict u from private.org_units where id=(p_payload->>'unit_id')::bigint and active;
  if u.revision is distinct from revision_value then raise exception 'اطلاعات هم‌زمان تغییر کرده؛ تازه‌سازی کنید.';end if;
  if jsonb_typeof(p_payload->'features') is distinct from 'array' then raise exception 'فهرست امکانات معتبر نیست.';end if;
  delete from private.org_unit_features where unit_id=u.id;
  for feature in select jsonb_array_elements_text(p_payload->'features') loop
   execute format('select feature_key from %I.app_features where feature_key=$1 and active and feature_key<>''organizationAdmin''',u.schema_name) into title_value using feature;
   if title_value is null then raise exception 'قابلیت معتبر نیست: %',feature;end if;
   insert into private.org_unit_features values(u.id,feature) on conflict do nothing;
  end loop;
  update private.org_units set features_configured=true,revision=revision+1 where id=u.id;
 elsif p_action='package' then
  if title_value is null or length(title_value)>160 then raise exception 'عنوان بسته معتبر نیست.';end if;
  if jsonb_typeof(p_payload->'grants') is distinct from 'array' then raise exception 'دسترسی‌های بسته معتبر نیست.';end if;
  if id_value is null then insert into private.org_packages(title) values(title_value) returning id into id_value;
  else update private.org_packages set title=title_value,active=coalesce((p_payload->>'active')::boolean,true),revision=revision+1 where id=id_value and revision=revision_value;get diagnostics affected=row_count;if affected<>1 then raise exception 'اطلاعات هم‌زمان تغییر کرده؛ تازه‌سازی کنید.';end if;end if;
  delete from private.org_package_grants where package_id=id_value;
  for entry in select * from jsonb_array_elements(p_payload->'grants') loop
   feature:=entry->>'feature_key';
   if not exists(select 1 from public.app_features where feature_key=feature and active and feature_key<>'organizationAdmin') then raise exception 'قابلیت بسته معتبر نیست.';end if;
   select array_agg(value) into actions_value from jsonb_array_elements_text(entry->'actions');
   actions_value:=coalesce(actions_value,array[]::text[]);
   if not actions_value <@ array['view','create','edit','delete','export'] then raise exception 'عملیات مدیریتی در بسته مجاز نیست.';end if;
   if feature in ('people','organization','systemOptions','templates','activeSessions','loginActivity') and not actions_value <@ array['view'] then raise exception 'مجوزهای مدیریتی این بخش از بسته‌های عمومی قابل واگذاری نیست.';end if;
   if cardinality(actions_value)>0 and not 'view'=any(actions_value) then actions_value:=array_prepend('view',actions_value);end if;
   insert into private.org_package_grants values(id_value,feature,actions_value);
  end loop;
 elsif p_action='binding_batch' then
  if jsonb_typeof(p_payload->'user_ids') is distinct from 'array' or jsonb_array_length(p_payload->'user_ids') not between 1 and 1000 then raise exception 'افراد را انتخاب کنید.';end if;
  for feature in select jsonb_array_elements_text(p_payload->'user_ids') loop
   perform public.admin_org_save('binding',(p_payload-'user_ids')||jsonb_build_object('user_id',feature));
  end loop;
 elsif p_action in ('membership','binding','position') then
  select * into strict u from private.org_units where id=(p_payload->>'unit_id')::bigint and active;
  ns:=u.schema_name;person:=nullif(p_payload->>'user_id','')::uuid;
  if person is not null then
   execute format('select id::text from %I.profiles where id=$1 and role<>''manager''',ns) into title_value using person;
   if title_value is null then raise exception 'کاربر عضو این محیط نیست یا حساب محافظت‌شده است.';end if;
  end if;
  if p_action='membership' then
   if person is null then raise exception 'فرد را انتخاب کنید.';end if;
   insert into private.org_members values(ns,person,u.id) on conflict(schema_name,user_id) do update set unit_id=excluded.unit_id;
   -- A move retires old package bindings; they must not revive if the user returns.
   update private.org_bindings set active=false where user_id=person and unit_id in(select id from private.org_units where schema_name=ns) and unit_id<>u.id;
   execute format('update %I.organization_positions set unit_id=$1 where id in(select position_id from %I.organization_position_assignments where user_id=$2 and is_primary and valid_from<=current_date and (valid_to is null or valid_to>current_date))',ns,ns) using u.local_unit_id,person;
  elsif p_action='binding' then
   if not exists(select 1 from private.org_packages where id=(p_payload->>'package_id')::bigint and active) then raise exception 'بسته معتبر نیست.';end if;
   if person is not null and not exists(select 1 from private.org_members where schema_name=ns and user_id=person and unit_id=u.id) then raise exception 'ابتدا واحد فرد را مشخص کنید.';end if;
   insert into private.org_bindings(package_id,unit_id,user_id,active) values((p_payload->>'package_id')::bigint,u.id,person,coalesce((p_payload->>'active')::boolean,true)) on conflict(package_id,unit_id,(coalesce(user_id,'00000000-0000-0000-0000-000000000000'::uuid))) do update set active=excluded.active;
  else
   perform public.admin_org_prepare_workspace(ns);
   if id_value is not null then
    execute format('select title from %I.organization_positions where id=$1 and unit_id=$2',ns) into title_value using id_value,u.local_unit_id;
    if title_value is null then raise exception 'سمت انتخاب‌شده متعلق به این واحد نیست.';end if;
   end if;
   execute format('select %I.save_organization_position($1,$2,$3,$4,$5)',ns) into saved using nullif(trim(p_payload->>'title'),''),(p_payload->>'role_id')::bigint,nullif(p_payload->>'parent_position_id','')::bigint,person,id_value;
   execute format('update %I.organization_positions set unit_id=$1 where id=$2',ns) using u.local_unit_id,(saved->>'position_id')::bigint;
   if person is not null then
    insert into private.org_members values(ns,person,u.id) on conflict(schema_name,user_id) do update set unit_id=excluded.unit_id;
    update private.org_bindings set active=false where user_id=person and unit_id in(select id from private.org_units where schema_name=ns) and unit_id<>u.id;
   end if;
  end if;
 else raise exception 'عملیات معتبر نیست.';end if;
 insert into private.org_admin_audit(actor_id,action,payload) values(auth.uid(),p_action,p_payload);
 -- Access changes reuse the existing realtime invalidation channel, without
 -- writing or deleting a person's direct grants.
 if p_action in ('features','package','binding','membership','department','unit') then
  foreach ns in array array['public','bamco_process','bamco_quality'] loop
   execute format('update %I.app_features set updated_at=now() where feature_key=''organizationAdmin''',ns);
  end loop;
 end if;
 return jsonb_build_object('ok',true,'id',id_value,'saved',saved);
end$$;

create function public.admin_org_effective(p_unit_id bigint,p_user_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare u private.org_units;ns text;result jsonb;begin
 perform private.org_require_admin();select * into strict u from private.org_units where id=p_unit_id;ns:=u.schema_name;
 if not exists(select 1 from private.org_members where unit_id=u.id and user_id=p_user_id and schema_name=ns) then raise exception 'فرد عضو این واحد نیست.';end if;
 execute format($q$select coalesce(jsonb_agg(jsonb_build_object('feature_key',f.feature_key,'title',f.title,'permissions',jsonb_build_object('view',(%2$I.feature_can_access_for($1,f.feature_key,'view') or (f.feature_key='kanban' and %2$I.kanban_supervision_enabled($1) and private.org_permission_decision(%1$L,$1,'kanban','view',null,null)<>-1)),'create',%2$I.feature_can_access_for($1,f.feature_key,'create'),'edit',(%2$I.feature_can_access_for($1,f.feature_key,'edit') or (f.feature_key='kanban' and %2$I.kanban_supervision_enabled($1) and private.org_permission_decision(%1$L,$1,'kanban','view',null,null)<>-1)),'delete',%2$I.feature_can_access_for($1,f.feature_key,'delete'),'export',%2$I.feature_can_access_for($1,f.feature_key,'export')),'unit_enabled',not $2 or exists(select 1 from private.org_unit_features x where x.unit_id=$3 and x.feature_key=f.feature_key),'direct_grants',(select coalesce(jsonb_agg(jsonb_build_object('effect',effect,'view',can_view,'create',can_create,'edit',can_edit,'delete',can_delete,'export',can_export)),'[]') from %1$I.feature_access_grants g where g.user_id=$1 and g.feature_key=f.feature_key and g.revoked_at is null and g.resource_type is null)) order by f.sort_order),'[]') from %1$I.app_features f where f.active$q$,ns,case ns when 'public' then 'private' else ns||'_private' end) into result using p_user_id,u.features_configured,u.id;
 return result;
end$$;

-- Same entry points in each workspace: one admin never has to sign out to
-- manage another namespace. The central guard always checks the global admin.
do $$declare ns text;fn text;begin
 foreach fn in array array['admin_org_snapshot()','admin_org_save(text,jsonb)','admin_org_effective(bigint,uuid)','admin_org_prepare_workspace(text)'] loop execute 'revoke all on function public.'||fn||' from public,anon';execute 'grant execute on function public.'||fn||' to authenticated';end loop;
 foreach ns in array array['bamco_process','bamco_quality'] loop
  execute format('create function %I.admin_org_snapshot() returns jsonb language sql security invoker set search_path='''' as $f$select public.admin_org_snapshot()$f$',ns);
  execute format('create function %I.admin_org_save(p_action text,p_payload jsonb) returns jsonb language sql security invoker set search_path='''' as $f$select public.admin_org_save(p_action,p_payload)$f$',ns);
  execute format('create function %I.admin_org_effective(p_unit_id bigint,p_user_id uuid) returns jsonb language sql security invoker set search_path='''' as $f$select public.admin_org_effective(p_unit_id,p_user_id)$f$',ns);
  execute format('create function %I.admin_org_prepare_workspace(p_schema text) returns boolean language sql security invoker set search_path='''' as $f$select public.admin_org_prepare_workspace(p_schema)$f$',ns);
  foreach fn in array array['admin_org_snapshot()','admin_org_save(text,jsonb)','admin_org_effective(bigint,uuid)','admin_org_prepare_workspace(text)'] loop execute 'revoke all on function '||quote_ident(ns)||'.'||fn||' from public,anon';execute 'grant execute on function '||quote_ident(ns)||'.'||fn||' to authenticated';end loop;
 end loop;
end$$;
do $$declare ns text;hidden text;definition text;needle text;begin
 foreach ns in array array['public','bamco_process','bamco_quality'] loop
  hidden:=case ns when 'public' then 'private' else ns||'_private' end;
  definition:=pg_get_functiondef(to_regprocedure(hidden||'.kanban_supervision_enabled(uuid)'));
  execute replace(definition,hidden||'.kanban_supervision_enabled(',hidden||'.kanban_supervision_before_org(');
  execute format('revoke all on function %I.kanban_supervision_before_org(uuid) from public,anon,authenticated',hidden);
  execute format('create or replace function %1$I.kanban_supervision_enabled(p_actor uuid) returns boolean language sql stable security definer set search_path='''' as $fn$select private.org_permission_decision(%2$L,p_actor,''kanban'',''view'',null,null)<>-1 and %1$I.kanban_supervision_before_org(p_actor)$fn$',hidden,ns);
  if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname=ns and tablename='app_features') then execute format('alter publication supabase_realtime add table %I.app_features',ns);end if;
 end loop;
end$$;
notify pgrst,'reload schema';
